        {
            nint description = 0;
            try
            {
                int hr = ((delegate* unmanaged<nint, nint*, int>)(*(void***)info)[5])(info, &description);
                return hr < 0 || description == 0 ? null : Marshal.PtrToStringBSTR(description);
            }
            finally
            {
                if (description != 0)
                {
                    Marshal.FreeBSTR(description);
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static nint CreateString(string? source)
        {
            if (source is null)
            {
                return 0;
            }
            fixed (char* buffer = source)
            {
                nint value = 0;
                int hr = WindowsCreateString((ushort*)buffer, (uint)source.Length, &value);
                if (hr < 0)
                {
                    DeleteHstring(ref value);
                    Com.Check(hr);
                }
                return value;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static nint CreateStringReference(ushort* source, uint length, HstringHeader* header)
        {
            nint value;
            Com.Check(WindowsCreateStringReference(source, length, header, &value));
            return value;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static string FromHstring(nint value)
        {
            if (value == 0)
            {
                return string.Empty;
            }
            try
            {
                return FromHstringBorrowed(value);
            }
            finally
            {
                _ = WindowsDeleteString(value);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static string FromHstringBorrowed(nint value)
        {
            if (value == 0)
            {
                return string.Empty;
            }
            ushort* buffer = WindowsGetStringRawBuffer(value, out uint length);
            return new string((char*)buffer, 0, (int)length);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static string TakeHstring(ref nint value)
        {
            nint current = value;
            value = 0;
            return FromHstring(current);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void DeleteHstring(ref nint value)
        {
            nint current = value;
            value = 0;
            if (current != 0)
            {
                _ = WindowsDeleteString(current);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool[] FromBooleanArray(ref uint length, ref byte* value)
        {
            uint count = length;
            byte* source = value;
            length = 0;
            value = null;
            try
            {
                bool[] result = new bool[count];
                fixed (bool* target = result)
                {
                    new ReadOnlySpan<byte>(source, checked((int)count)).CopyTo(new Span<byte>((byte*)target, checked((int)count)));
                }
                return result;
            }
            finally
            {
                Marshal.FreeCoTaskMem((nint)source);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static TSurface[] FromArray<TSurface, TAbi>(ref uint length, ref TAbi* value) where TSurface : unmanaged where TAbi : unmanaged
        {
            uint count = length;
            TAbi* source = value;
            length = 0;
            value = null;
            try
            {
                if (sizeof(TSurface) != sizeof(TAbi))
                {
                    throw new InvalidOperationException("Array surface and ABI element sizes differ.");
                }
                TSurface[] result = new TSurface[count];
                if (count != 0)
                {
                    fixed (TSurface* target = result)
                    {
                        long bytes = checked((long)count * sizeof(TSurface));
                        Buffer.MemoryCopy(source, target, bytes, bytes);
                    }
                }
                return result;
            }
            finally
            {
                Marshal.FreeCoTaskMem((nint)source);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static string[] FromStringArray(ref uint length, ref nint* value)
        {
            uint count = length;
            nint* source = value;
            length = 0;
            value = null;
            try
            {
                string[] result = new string[count];
                for (uint i = 0; i < count; i++)
                {
                    nint current = source[i];
                    source[i] = 0;
                    result[i] = FromHstring(current);
                }
                return result;
            }
            finally
            {
                FreeStringArray(count, source);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static T?[] FromObjectArray<T>(ref uint length, ref nint* value) where T : ComObject, IComInterface<T>
        {
            uint count = length;
            nint* source = value;
            length = 0;
            value = null;
            T?[]? result = null;
            uint converted = 0;
            try
            {
                result = new T?[count];
                for (; converted < count; converted++)
                {
                    nint current = source[converted];
                    source[converted] = 0;
                    result[converted] = Com.Wrap<T>(current);
                }
                return result;
            }
            catch
            {
                if (result is not null)
                {
                    for (uint i = 0; i < converted; i++)
                    {
                        result[i]?.Dispose();
                    }
                }
                throw;
            }
            finally
            {
                FreeObjectArray(count, source);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void FreeStringArray(uint length, nint* value)
        {
            if (value == null)
            {
                return;
            }
            for (uint i = 0; i < length; i++)
            {
                if (value[i] != 0)
                {
                    _ = WindowsDeleteString(value[i]);
                }
            }
            Marshal.FreeCoTaskMem((nint)value);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void FreeObjectArray(uint length, nint* value)
        {
            if (value == null)
            {
                return;
            }
            for (uint i = 0; i < length; i++)
            {
                if (value[i] != 0)
                {
                    _ = Com.Release(value[i]);
                }
            }
            Marshal.FreeCoTaskMem((nint)value);
        }

        [StructLayout(LayoutKind.Sequential, Size = 24)]
        public struct HstringHeader { }
    }
}
